a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_plsrcox.R <dev> <val> <out> [vars] [seed]");if(!requireNamespace("plsRcox",quietly=TRUE))stop("Install plsRcox");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(a)>=5)as.integer(a[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);set.seed(seed);cv<-plsRcox::cv.plsRcox(list(x=tr[,v,drop=FALSE],time=tr$Time,status=tr$Event),nt=min(10,length(v)),nfold=10,verbose=FALSE);nt<-if(!is.null(cv$nt.opt))cv$nt.opt else 3L;fit<-plsRcox::plsRcox(tr[,v,drop=FALSE],time=tr$Time,event=tr$Event,nt=nt);score<-function(d)as.numeric(predict(fit,newdata=as.matrix(d[,v,drop=FALSE]),type="risk"));write.csv(data.frame(Time=tr$Time,Event=tr$Event,plsRcox=score(tr)),file.path(out,"development_plsrcox_predictions.csv"),row.names=FALSE);write.csv(data.frame(Time=va$Time,Event=va$Event,plsRcox=score(va)),file.path(out,"validation_plsrcox_predictions.csv"),row.names=FALSE);saveRDS(list(model=fit,cv=cv,nt=nt,predictors=v),file.path(out,"plsrcox_model.rds"))
